<?php

declare(strict_types=1);

use Illuminate\Foundation\Testing\RefreshDatabase;
use Modules\Sample\Models\Sample;
use Modules\Sample\Widgets\JumlahBaru;
use Yuan\AdminCore\Testing\ModuleAssertions;

// The JumlahBaru widget on Beranda (generated by make:widget): permission, scope, time budget.

uses(RefreshDatabase::class);

it('is missing from Beranda without samples.view', function (): void {
    ModuleAssertions::assertWidgetHiddenWithout(JumlahBaru::class);
});

it('reads only the records the user may see', function (): void {
    ModuleAssertions::actingAsLevelWith(['dashboard.view', 'samples.view']);

    ModuleAssertions::assertWidgetUsesScope(JumlahBaru::class, Sample::class);
});

it('stays within the widget time budget', function (): void {
    Sample::factory()->count(200)->create();
    ModuleAssertions::actingAsLevelWith(['dashboard.view', 'samples.view']);

    ModuleAssertions::assertWidgetWithinBudget(JumlahBaru::class);
});
